import fitz, numpy as np
d=fitz.open('eprint/Fig9a.pdf')
p=d[0]
target=(0.26357999444007874, 0.2208860069513321, 0.7407379746437073)
pts=[]
for dr in p.get_drawings():
    if dr['type']=='s' and dr.get('color')==target:
        for it in dr['items']:
            if it[0]=='l':
                if not pts: pts.append((it[1].x,it[1].y))
                pts.append((it[2].x,it[2].y))
            elif it[0]=='c':
                if not pts: pts.append((it[1].x,it[1].y))
                pts.append((it[4].x,it[4].y))
pts=np.array(pts)
print(len(pts), pts[:5], pts[-5:])
m = 5 + (pts[:,0]-65.0)*20/(491.0-65.0)
g = 10**(-12 + (323.199-pts[:,1])/138.95)
for i in range(0,len(pts),8):
    print(f"{m[i]:.2f} {g[i]:.3e}")
print(f"{m[-1]:.2f} {g[-1]:.3e}")
np.save('curve.npy', np.column_stack([m,g]))
